\textup{(\cref{invaraiant})}
    Let $V_\eta \in \mathcal{C}$ be an ambidextrous module and $L$ a framed link with at least one strand colored by $V_\alpha$ for some $\alpha \in \mathbb{C} \setminus \mathbb{Z} \cup r \mathbb{Z}$. Then the assignment
		\begin{equation*}
			L \mapsto F_\eta'(L) := \mathbf{d}_\eta(\alpha) F_\mathcal{C}(T),
		\end{equation*}
	where $T$ is a $(1,1)$-tangle whose closure is $L$ and whose open strand is colored by $V_{\alpha}$, is a well-defined isotopy invariant of framed colored links.

\label{simplemodules}
Let $\alpha \in \mathbb{C}$.
    \begin{enumerate}
        \item \label{eins} If $\alpha \notin \mathbb{Z} \setminus r \mathbb{Z}$, then $V_{\alpha}$ is simple.
        \item \label{zwei} If $\alpha \in \mathbb{Z} \setminus r\mathbb{Z}$ is written in its unique form as $\alpha = (l-1)r + n + 1$ with $0 \leq n \leq r-2$ and $l \in \mathbb{Z}$, then there exists a non-split short exact sequence $$ 0 \rightarrow S_{r-n-2}^{(l-1)r} \rightarrow V_\alpha \rightarrow S_{n}^{lr} \rightarrow 0$$ which is a Jordan--H\"{o}lder filtration of $V_{\alpha}$.
        \item \label{drei} Any simple object of $\mathcal{C}$ is isomorphic to a unique module of the form $V_\alpha$, $\alpha \in \mathbb{C} \setminus \mathbb{Z} \cup r \mathbb{Z}$, or $S_n^{lr}$, $l \in \mathbb{Z}$, $0 \leq n \leq r-2$.
    \end{enumerate}

\label{rotate}
	For any $V, W \in \mathcal{D}$, the following equality of morphisms in $\mathcal{D}$ holds:
	\begin{equation}\label{rotate_loop}
