			\,=\, F_\mathcal{D} \left (
			\begin{tikzpicture}[anchorbase,scale=0.8]
				\draw [very thick, postaction={decorate}, decoration={markings, mark=at position 0.65 with {\arrow{<}}}] (.1,.5) to [out=0,in=90] (.8,0) to [out=270,in=0] (0,-.5) to [out=180,in=270] (-.8,0) to [out=90,in=180] (-.1,.5);
